insert into public.study_tests(id,title,subject,grade,level,path,questions) values('organizmy5-v1','Organizmy','Biologia','5','','testy/biologia/organizmy-5.html','[{"no":1,"question":"Samochód porusza się i zużywa paliwo. Dlaczego mimo to nie jest organizmem?","topic":"Czynności życiowe","options":["Każdy organizm musi mieć liście.","Ruch i zużywanie energii nie wystarczą: samochód nie ma budowy komórkowej ani pełnego zestawu czynności życiowych.","Organizmy nigdy się nie poruszają.","Organizmem jest każdy przedmiot, który się porusza."],"correct":1,"explanation":"Organizmy mają budowę komórkową i wykonują czynności życiowe. Sam ruch nie oznacza, że coś żyje."},{"no":2,"question":"Która struktura otacza każdą komórkę i reguluje, jakie substancje dostają się do niej oraz z niej wydostają?","topic":"Budowa komórki","options":["Błona komórkowa.","Chloroplast.","Ściana komórkowa.","Jądro komórkowe."],"correct":0,"explanation":"Błona komórkowa oddziela wnętrze komórki od otoczenia i kontroluje wymianę substancji. Nie każda komórka ma ścianę lub jądro."},{"no":3,"question":"W typowej komórce liścia występują chloroplasty. Jaką pełnią funkcję?","topic":"Budowa komórki","options":["Kierują ruchem całego zwierzęcia.","Usuwają wszystkie substancje z komórki.","Umożliwiają fotosyntezę dzięki zawartemu w nich chlorofilowi.","Zastępują błonę komórkową."],"correct":2,"explanation":"W chloroplastach zachodzi fotosynteza. Chlorofil pochłania energię światła potrzebną do tego procesu."},{"no":4,"question":"Bakteria jest organizmem jednokomórkowym. Co to oznacza?","topic":"Jednokomórkowe i wielokomórkowe","options":["Ma tylko jedno jądro, ale wiele komórek.","Składa się z jednej komórki, która wykonuje czynności życiowe całego organizmu.","Nie ma żadnych komórek.","Zawsze żyje tylko jeden dzień."],"correct":1,"explanation":"Jednokomórkowy oznacza zbudowany z jednej komórki. U bakterii nie występuje jądro komórkowe."},{"no":5,"question":"Która para poprawnie opisuje sposób odżywiania organizmów?","topic":"Samożywność i cudzożywność","options":["Dąb jest cudzożywny, a kot samożywny.","Dąb i kot wytwarzają pokarm dzięki fotosyntezie.","Kot wytwarza pokarm z wody i dwutlenku węgla.","Dąb jest samożywny, a kot cudzożywny."],"correct":3,"explanation":"Dąb wytwarza związki organiczne w fotosyntezie. Kot pobiera gotowy pokarm, dlatego jest cudzożywny."},{"no":6,"question":"Co roślina wykorzystuje podczas fotosyntezy do wytwarzania cukru?","topic":"Fotosynteza","options":["Wodę i dwutlenek węgla oraz energię światła.","Tylko tlen, bez wody i światła.","Gotowe mięso oraz glebę.","Tylko składniki mineralne, bez energii."],"correct":0,"explanation":"Roślina wykorzystuje wodę i dwutlenek węgla. Energia światła umożliwia wytwarzanie cukru; wydziela się również tlen."},{"no":7,"question":"Oddychanie komórkowe służy przede wszystkim do:","topic":"Oddychanie","options":["Zamiany każdej komórki w liść.","Wytwarzania pokarmu przy udziale światła.","Uwalniania energii z substancji pokarmowych.","Pobierania wyłącznie soli mineralnych."],"correct":2,"explanation":"Podczas oddychania komórkowego uwalniana jest energia potrzebna do czynności życiowych. Oddychanie komórkowe nie jest tym samym co wdech i wydech."},{"no":8,"question":"Roślina na parapecie wygina pęd w stronę okna. Jaką czynność życiową ilustruje ta obserwacja?","topic":"Reagowanie na bodźce","options":["Rozmnażanie, bo powstają nasiona.","Reagowanie na bodziec, którym jest światło.","Wydalanie, bo pęd zmienia kierunek.","Brak czynności życiowych, bo rośliny na nic nie reagują."],"correct":1,"explanation":"Światło jest bodźcem. Wzrost pędu w jego kierunku pokazuje, że rośliny reagują na zmiany w otoczeniu."},{"no":9,"question":"Który przykład najlepiej pokazuje rozwój, czyli zmiany w budowie i funkcjonowaniu organizmu?","topic":"Wzrost i rozwój","options":["Ołówek został wydłużony przez dołączenie gumki.","Kamień rozpadł się na dwie części.","Szklankę napełniono wodą.","Kijanka przekształciła się w żabę."],"correct":3,"explanation":"Kijanka zmienia budowę i sposób funkcjonowania, np. wyrastają jej kończyny. Rozwój nie oznacza tylko zwiększenia rozmiarów."},{"no":10,"question":"Która kolejność prawidłowo przedstawia organizację budowy człowieka od prostszych elementów do bardziej złożonych?","topic":"Budowa organizmu","options":["Komórka → tkanka → narząd → układ narządów → organizm.","Organizm → komórka → narząd → tkanka → układ narządów.","Tkanka → komórka → organizm → narząd → układ narządów.","Narząd → tkanka → komórka → organizm → układ narządów."],"correct":0,"explanation":"Komórki tworzą tkanki, tkanki budują narządy, a współpracujące narządy tworzą układy narządów. Wszystkie układy są częścią organizmu."}]'::jsonb);